  const safeMode = attempt === MAX_ATTEMPTS;
  const _DIAG_PROMPTS = [
    'Group of 3 young Latin American professionals in a modern glass-walled open-plan office, seen from behind looking at a large wall panel, warm soft ambient lighting, premium editorial photography, no text on any surface, no readable screens, no signage, calm lower third for text overlay',
