    'Group of 4 diverse young Latin American professionals in a sleek modern tech office, seen from a slightly elevated angle, working and collaborating, warm ambient light, no text on surfaces, no readable screens, premium cinematic',
    'Young Latina entrepreneur in a bright open co-working space, side view at a standing desk, large windows with blurred city behind, confident posture, warm golden light, premium editorial photography, no text anywhere, calm lower third',
    'Group of 3 Latin American business professionals in a modern conference room with glass walls, seen from the side, engaged in discussion, soft natural light, no text on surfaces, no readable screens, premium editorial, calm lower third',
  ];
  const prompt = (_diagram_type && !safeMode)
    ? _DIAG_PROMPTS[Math.floor(Math.random() * _DIAG_PROMPTS.length)]
    : (safeMode ? safeFallbackPrompt(prev) : prev.image_prompt);
  usedSafeFallback = usedSafeFallback || safeMode;
  const resp = await generateIdeogram(prompt, prev.aspect_ratio, safeMode);
  const url = resp.data?.[0]?.url;
  if (!url) throw new Error('Ideogram sin URL en intento ' + attempt + ': ' + JSON.stringify(resp).slice(0, 300));
  const ocr = await checkOCR(url);
  if (ocr.hasText) {
    lastError = 'Intento ' + attempt + (safeMode ? ' fallback seguro' : '') + ': texto detectado - "' + ocr.detectedText.replace(/"/g, "'").slice(0, 100) + '"';
    console.log('[OCR] ' + lastError);
    continue;
  }
  if (HAS_PEOPLE) {
    const anatomy = await checkAnatomy(url);
    if (anatomy.bad) {
      lastError = 'Intento ' + attempt + (safeMode ? ' fallback seguro' : '') + ': anatomia deforme - "' + anatomy.reason.replace(/"/g, "'") + '"';
      console.log('[Anatomy] ' + lastError);
      continue;
    }
  }
  cleanImageUrl = url;
  console.log('[QA] Intento ' + attempt + (safeMode ? ' fallback seguro' : '') + ': imagen limpia (texto + anatomia OK)');
  break;
}

if (cleanImageUrl) {
  return [{ json: { ...prev, data: [{ url: cleanImageUrl }], used_safe_fallback: usedSafeFallback, diagram_type: _diagram_type } }];
}
